// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INIT_DISTRIBUTED = 200000000e18;

    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != address(0) && b != address(0));
        vm.assume(a != b);
        vm.assume(a != address(this) && b != address(this));

        // Both actors claim the free airdrop through the public entry getTokens
        vm.prank(a);
        c.getTokens();
        vm.prank(b);
        c.getTokens();

        uint256 balA = c.balanceOf(a);
        uint256 balB = c.balanceOf(b);
        uint256 distGrowth = c.totalDistributed() - INIT_DISTRIBUTED;

        // General rule: tokens credited to recipients exactly accumulate —
        // the sum of their balances equals the total amount recorded as distributed.
        assertTrue(balA + balB == distGrowth);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // An arbitrary actor participates in the airdrop (same effect in P and M).
        vm.prank(actor);
        c.getTokens();
        assertTrue(c.blacklist(actor));

        // Owner initializes its own balance via XBornID (owner == deployer == this contract).
        c.XBornID();
        assertEq(c.balanceOf(address(this)), c.totalDistributed());

        // Owner receives an additional distribution: balances must ACCUMULATE,
        // so the owner's balance keeps matching the accumulated totalDistributed.
        c.getTokens();

        // General rule: balance of the repeatedly-credited account equals the
        // accumulated distribution total. Holds in P for every input;
        // the mutant's overwrite breaks it for every input.
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

