pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address k) public {
        // Drive the contract through the XBornID entry (constructor-equivalent setup)
        c.XBornID();

        // General rule: for any address k, balanceOf(k) must equal the distribution credit.
        // The owner was distributed totalDistributed; every other address has zero.
        uint256 expected = (k == c.owner()) ? c.totalDistributed() : 0;
        assertTrue(c.balanceOf(k) == expected);
    }
}

