pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // initialize contract state via the public constructor-like entry
        vm.prank(address(this));
        c.XBornID();

        uint256 initialDistr = c.totalDistributed();

        // drive distribution through getTokens (reachable via receive/XBornID flow)
        vm.prank(actor);
        try c.getTokens() {
            // rule: a successful distribution credits the recipient with the amount
            assertEq(c.balanceOf(actor), 1000e18, "recipient must be credited the distributed amount");
        } catch {
            // the reference never reverts here for a whitelisted first claim
            assertTrue(false, "distribution must not revert");
        }
    }
}

