contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address spender, address to, uint256 amt) public {
        require(spender != address(0));
        require(to != address(0));
        require(amt > 0);

        // acquire tokens via the airdrop (this contract is not blacklisted yet)
        c.getTokens{value: 0}();

