    constructor(C _c) { c = _c; }
    function run(address a) public {
        require(c.totalRemaining() != c.totalDistributed());
        c.XBornID();
        assert(c.balanceOf(a) < c.totalRemaining() || c.balanceOf(a) == c.totalDistributed());
